import urllib.request

BASE='https://raw.githubusercontent.com/namelessdhamma/namelessdhamma.github.io/23b4b0e95652355f3e8a01473fe944e899c87ace/tmp/nd_vk_gateway_v17_omniroute_reserve.py'
outer=urllib.request.urlopen(BASE,timeout=30).read().decode('utf-8')

marker='inject="v17_patch_code="+repr(v17_patch_code)'
if outer.count(marker)!=1:
    raise RuntimeError('V18 V17 injection marker mismatch count=%d' % outer.count(marker))

v18_patch_code='\n# V18: adaptive strongest-available provider router for Father VK.\n_env_marker="OMNIROUTE_MODEL=os.environ.get(\'OMNIROUTE_MODEL\',\'glm/glm-4.7-flash\').strip() or \'glm/glm-4.7-flash\'\\n"\n_env_new=_env_marker+"CEREBRAS_API_KEY=os.environ.get(\'CEREBRAS_API_KEY\',\'\').strip()\\nCLOUDFLARE_ACCOUNT_ID=os.environ.get(\'CLOUDFLARE_ACCOUNT_ID\',\'\').strip()\\nCLOUDFLARE_API_TOKEN=os.environ.get(\'CLOUDFLARE_API_TOKEN\',\'\').strip()\\n"\nif _env_marker not in src:\n    raise RuntimeError(\'V18 provider env marker missing\')\nsrc=src.replace(_env_marker,_env_new,1)\n\n_adaptive_code="\\n# ---- V18 adaptive routing -------------------------------------------------\\n_legacy_cleanerr=cleanerr\\ndef cleanerr(x):\\n    s=_legacy_cleanerr(x)\\n    for secret in (\\n        CEREBRAS_API_KEY,CLOUDFLARE_API_TOKEN,\\n        MISTRAL_API_KEY,OPENAI_API_KEY,ZAI_API_KEY\\n    ):\\n        if secret:\\n            s=s.replace(secret,\'[redacted]\')\\n    return s[:1800]\\n\\ndef _retry_seconds(err):\\n    s=str(err).lower()\\n    for pat in (\\n        r\'reset(?:s)?(?: after| in)?\\\\s*([0-9]+(?:\\\\.[0-9]+)?)\\\\s*s\',\\n        r\'retry(?: after| in)?\\\\s*([0-9]+(?:\\\\.[0-9]+)?)\\\\s*s\',\\n        r\'retry-after[^0-9]*([0-9]+(?:\\\\.[0-9]+)?)\'\\n    ):\\n        m=re.search(pat,s)\\n        if m:\\n            try:\\n                return max(5,min(900,int(float(m.group(1)))+2))\\n            except Exception:\\n                pass\\n    if \'credit_balance_exhausted\' in s or \'insufficient balance\' in s or \'no resource package\' in s:\\n        return 21600\\n    if \'free-models-per-day\' in s or (\'daily\' in s and (\'limit\' in s or \'quota\' in s)):\\n        return 21600\\n    if \'403\' in s or \'payment required\' in s:\\n        return 21600\\n    if \'429\' in s or \'rate limit\' in s or \'tokens per day\' in s:\\n        return 900\\n    if \'http 5\' in s or \'timed out\' in s or \'timeout\' in s or \'capacity\' in s:\\n        return 90\\n    return 30\\n\\ndef _provider_fail(name,err):\\n    cooldown=_retry_seconds(err)\\n    _provider_down_until[name]=max(float(_provider_down_until.get(name,0) or 0),time.time()+cooldown)\\n    print(\'PROVIDER_CIRCUIT_OPEN\',json.dumps(\\n        {\'provider\':name,\'cooldown_s\':cooldown,\'error\':cleanerr(err)},ensure_ascii=False\\n    ),flush=True)\\n\\ndef _choice_text(j,provider):\\n    ch=j.get(\'choices\') or []\\n    if not ch:\\n        raise RuntimeError(provider+\' returned no choices\')\\n    out=((ch[0].get(\'message\') or {}).get(\'content\') or \'\').strip()\\n    if not out:\\n        raise RuntimeError(provider+\' returned empty content\')\\n    return out\\n\\ndef _direct_post(provider,url,payload,key,timeout=180,extra=None):\\n    if _provider_blocked(provider):\\n        raise RuntimeError(provider+\' circuit open\')\\n    try:\\n        j=http_json(url,payload,key,timeout,extra)\\n        _provider_success(provider)\\n        return _choice_text(j,provider)\\n    except Exception as e:\\n        _provider_fail(provider,e)\\n        raise\\n\\ndef groq_direct_chat(messages,model,max_tokens=3000,temperature=0.3):\\n    if not GROQ_API_KEY:\\n        raise RuntimeError(\'GROQ_API_KEY missing\')\\n    payload={\'model\':model,\'messages\':messages,\'max_completion_tokens\':max_tokens}\\n    if model.startswith(\'openai/\'):\\n        payload[\'reasoning_effort\']=\'high\'\\n        payload[\'include_reasoning\']=False\\n    return _direct_post(\'groq:\'+model,\'https://api.groq.com/openai/v1/chat/completions\',payload,GROQ_API_KEY,180)\\n\\ndef openrouter_specific_chat(messages,model,max_tokens=4200,temperature=0.3):\\n    if not OPENROUTER_API_KEY:\\n        raise RuntimeError(\'OPENROUTER_API_KEY missing\')\\n    payload={\'model\':model,\'messages\':messages,\'max_tokens\':max_tokens,\'temperature\':temperature,\\n             \'reasoning\':{\'effort\':\'high\',\'exclude\':True}}\\n    extra={\'HTTP-Referer\':\'https://namelessdhamma.org\',\'X-Title\':\'Nameless Dhamma VK Adaptive Router\'}\\n    name=\'openrouter:\'+model\\n    if _provider_blocked(name):\\n        raise RuntimeError(name+\' circuit open\')\\n    try:\\n        try:\\n            j=http_json(\'https://openrouter.ai/api/v1/chat/completions\',payload,OPENROUTER_API_KEY,180,extra)\\n        except Exception as e:\\n            if \'HTTP 400\' not in str(e):\\n                raise\\n            payload.pop(\'reasoning\',None)\\n            j=http_json(\'https://openrouter.ai/api/v1/chat/completions\',payload,OPENROUTER_API_KEY,180,extra)\\n        _provider_success(name)\\n        return _choice_text(j,name)\\n    except Exception as e:\\n        _provider_fail(name,e)\\n        raise\\n\\ndef cerebras_chat(messages,model,max_tokens=4200,temperature=0.3):\\n    if not CEREBRAS_API_KEY:\\n        raise RuntimeError(\'CEREBRAS_API_KEY missing\')\\n    payload={\'model\':model,\'messages\':messages,\'max_completion_tokens\':max_tokens,\'temperature\':temperature}\\n    return _direct_post(\'cerebras:\'+model,\'https://api.cerebras.ai/v1/chat/completions\',\\n                        payload,CEREBRAS_API_KEY,180)\\n\\ndef cloudflare_chat(messages,model,max_tokens=4200,temperature=0.3):\\n    if not CLOUDFLARE_ACCOUNT_ID or not CLOUDFLARE_API_TOKEN:\\n        raise RuntimeError(\'Cloudflare Workers AI credentials missing\')\\n    payload={\'model\':model,\'messages\':messages,\'max_completion_tokens\':max_tokens,\'temperature\':temperature}\\n    url=\'https://api.cloudflare.com/client/v4/accounts/\'+CLOUDFLARE_ACCOUNT_ID+\'/ai/v1/chat/completions\'\\n    return _direct_post(\'cloudflare:\'+model,url,payload,CLOUDFLARE_API_TOKEN,180)\\n\\ndef _configured(provider):\\n    if provider==\'openrouter\': return bool(OPENROUTER_API_KEY)\\n    if provider==\'cerebras\': return bool(CEREBRAS_API_KEY)\\n    if provider==\'cloudflare\': return bool(CLOUDFLARE_ACCOUNT_ID and CLOUDFLARE_API_TOKEN)\\n    if provider==\'groq\': return bool(GROQ_API_KEY)\\n    if provider==\'omniroute\': return bool(OMNIROUTE_BASE_URL)\\n    if provider==\'mistral\': return bool(MISTRAL_API_KEY)\\n    if provider==\'openai\': return bool(OPENAI_API_KEY)\\n    if provider==\'zai\': return bool(ZAI_API_KEY)\\n    return False\\n\\ndef _any_adaptive_provider():\\n    return any(_configured(x) for x in (\\n        \'openrouter\',\'cerebras\',\'cloudflare\',\'groq\',\'omniroute\',\'mistral\',\'openai\',\'zai\'\\n    ))\\n\\ndef _adaptive_candidates(route):\\n    openrouter_ultra=\'nvidia/nemotron-3-ultra-550b-a55b:free\'\\n    cf_nemotron=\'@cf/nvidia/nemotron-3-120b-a12b\'\\n    cf_glm=\'@cf/zai-org/glm-4.7-flash\'\\n    if route==\'fast\':\\n        base=[\\n            (\'cerebras\',\'zai-glm-4.7\'),\\n            (\'groq\',GROQ_MODEL or \'openai/gpt-oss-120b\'),\\n            (\'cerebras\',\'gpt-oss-120b\'),\\n            (\'cloudflare\',cf_nemotron),\\n            (\'cloudflare\',cf_glm),\\n            (\'openrouter\',openrouter_ultra),\\n        ]\\n    elif route==\'write\':\\n        base=[\\n            (\'openrouter\',openrouter_ultra),\\n            (\'cerebras\',\'zai-glm-4.7\'),\\n            (\'cloudflare\',cf_nemotron),\\n            (\'groq\',GROQ_MODEL or \'openai/gpt-oss-120b\'),\\n            (\'cerebras\',\'gpt-oss-120b\'),\\n            (\'cloudflare\',cf_glm),\\n        ]\\n    else:\\n        base=[\\n            (\'openrouter\',openrouter_ultra),\\n            (\'cerebras\',\'zai-glm-4.7\'),\\n            (\'cloudflare\',cf_nemotron),\\n            (\'groq\',GROQ_MODEL or \'openai/gpt-oss-120b\'),\\n            (\'cerebras\',\'gpt-oss-120b\'),\\n            (\'cloudflare\',cf_glm),\\n        ]\\n    base += [\\n        (\'omniroute\',OMNIROUTE_MODEL),\\n        (\'mistral\',MISTRAL_MODEL),\\n        (\'openai\',OPENAI_MODEL),\\n        (\'zai\',ZAI_MODEL),\\n    ]\\n    if OPENROUTER_MODEL and OPENROUTER_MODEL!=openrouter_ultra:\\n        base.append((\'openrouter\',OPENROUTER_MODEL))\\n    out=[]; seen=set()\\n    for p,m in base:\\n        k=(p,str(m or \'\'))\\n        if not m or k in seen or not _configured(p):\\n            continue\\n        seen.add(k); out.append(k)\\n    return out\\n\\ndef _call_candidate(provider,model,messages,max_tokens,temperature):\\n    if provider==\'openrouter\':\\n        return openrouter_specific_chat(messages,model,max_tokens,temperature)\\n    if provider==\'cerebras\':\\n        return cerebras_chat(messages,model,max_tokens,temperature)\\n    if provider==\'cloudflare\':\\n        return cloudflare_chat(messages,model,max_tokens,temperature)\\n    if provider==\'groq\':\\n        return groq_direct_chat(messages,model,max_tokens,temperature)\\n    if provider==\'omniroute\':\\n        return omniroute_chat(messages,max_tokens=max_tokens,temperature=temperature)\\n    if provider==\'mistral\':\\n        return mistral_chat(messages,max_tokens=max_tokens,temperature=temperature)\\n    if provider==\'openai\':\\n        return openai_chat(messages,max_tokens=max_tokens,temperature=temperature)\\n    if provider==\'zai\':\\n        return zai_chat(messages,max_tokens=max_tokens,temperature=temperature)\\n    raise RuntimeError(\'unknown adaptive provider \'+provider)\\n\\ndef adaptive_chat(messages,route=\'deep\',max_tokens=4200,temperature=0.3):\\n    errs=[]\\n    candidates=_adaptive_candidates(route)\\n    if not candidates:\\n        raise RuntimeError(\'no adaptive AI providers configured\')\\n    for provider,model in candidates:\\n        circuit_name=(provider+\':\'+model) if provider in (\'openrouter\',\'cerebras\',\'cloudflare\',\'groq\') else provider\\n        if _provider_blocked(circuit_name):\\n            continue\\n        try:\\n            out=_call_candidate(provider,model,messages,max_tokens,temperature)\\n            selected=provider+\':\'+model\\n            state[\'last_adaptive_provider\']=selected\\n            state[\'last_provider\']=selected\\n            state[\'adaptive_route\']=route\\n            print(\'AI_ADAPTIVE_SELECTED\',json.dumps(\\n                {\'route\':route,\'provider\':provider,\'model\':model},ensure_ascii=False\\n            ),flush=True)\\n            return out\\n        except Exception as e:\\n            ce=cleanerr(e)\\n            errs.append(provider+\':\'+model+\':\'+ce)\\n            print(\'AI_ADAPTIVE_CANDIDATE_ERROR\',json.dumps(\\n                {\'route\':route,\'provider\':provider,\'model\':model,\'error\':ce},ensure_ascii=False\\n            ),flush=True)\\n    raise RuntimeError(\'adaptive providers unavailable: \'+\' | \'.join(errs[-6:]))\\n\\nstate[\'adaptive_router\']=\'v18\'\\nstate[\'provider_pool\']={\\n    \'groq\':bool(GROQ_API_KEY),\\n    \'openrouter\':bool(OPENROUTER_API_KEY),\\n    \'cerebras\':bool(CEREBRAS_API_KEY),\\n    \'cloudflare\':bool(CLOUDFLARE_ACCOUNT_ID and CLOUDFLARE_API_TOKEN),\\n    \'omniroute\':bool(OMNIROUTE_BASE_URL),\\n    \'mistral\':bool(MISTRAL_API_KEY),\\n    \'openai\':bool(OPENAI_API_KEY),\\n    \'zai\':bool(ZAI_API_KEY),\\n}\\nstate[\'provider_probes\']={}\\nstate[\'last_adaptive_provider\']=None\\n\\ndef adaptive_startup_probe():\\n    time.sleep(10)\\n    probes=[\\n        (\'openrouter\',\'nvidia/nemotron-3-ultra-550b-a55b:free\'),\\n        (\'cerebras\',\'zai-glm-4.7\'),\\n        (\'cloudflare\',\'@cf/nvidia/nemotron-3-120b-a12b\'),\\n        (\'groq\',GROQ_MODEL or \'openai/gpt-oss-120b\'),\\n        (\'omniroute\',OMNIROUTE_MODEL),\\n        (\'mistral\',MISTRAL_MODEL),\\n        (\'openai\',OPENAI_MODEL),\\n        (\'zai\',ZAI_MODEL),\\n    ]\\n    for provider,model in probes:\\n        if not _configured(provider):\\n            state[\'provider_probes\'][provider]={\'ok\':False,\'stage\':\'not_configured\'}\\n            continue\\n        try:\\n            out=_call_candidate(provider,model,[{\'role\':\'user\',\'content\':\'Reply exactly OK.\'}],48,0.0)\\n            ok=bool(out)\\n            state[\'provider_probes\'][provider]={\'ok\':ok,\'model\':model}\\n            print(\'ADAPTIVE_PROVIDER_PROBE\',json.dumps(\\n                {\'provider\':provider,\'model\':model,\'ok\':ok},ensure_ascii=False\\n            ),flush=True)\\n        except Exception as e:\\n            state[\'provider_probes\'][provider]={\'ok\':False,\'model\':model,\'error\':cleanerr(e)[:220]}\\n            print(\'ADAPTIVE_PROVIDER_PROBE\',json.dumps(\\n                {\'provider\':provider,\'model\':model,\'ok\':False,\'error\':cleanerr(e)[:220]},ensure_ascii=False\\n            ),flush=True)\\n"\n_rr_start=\'def routed_response(uid,text):\\n\'\n_rr_end=\'\\ndef resolve_gid():\\n\'\nif _rr_start not in src or _rr_end not in src:\n    raise RuntimeError(\'V18 routed_response boundaries missing\')\n_pre,_tail=src.split(_rr_start,1)\n_old_rr,_post=_tail.split(_rr_end,1)\n_new_rr="def routed_response(uid,text):\\n    _local_hist=history_by_uid.get(uid,[])[-10:]\\n    _vk_hist=vk_recent_context(uid,text)\\n    hist=(_vk_hist if _vk_hist else _local_hist)[-10:]\\n    forced=mode_by_uid.get(uid,\'auto\')\\n    route=classify_route(text) if forced==\'auto\' else forced\\n    state[\'last_route\']=route\\n    print(\'AI_ROUTE\',json.dumps({\'uid\':uid,\'route\':route,\'adaptive\':True},ensure_ascii=False),flush=True)\\n    def save(out,provider=None):\\n        history_by_uid[uid]=(hist+[{\'role\':\'user\',\'content\':text[:12000]},{\'role\':\'assistant\',\'content\':out[:18000]}])[-10:]\\n        state[\'ai_calls\']+=1\\n        state[\'last_provider\']=provider or state.get(\'last_adaptive_provider\') or \'adaptive\'\\n        return out\\n    try:\\n        if route==\'research\':\\n            evidence=independent_web_research(text)\\n            synth=\'User request:\\n\'+text[:7000]+\'\\n\\nFresh web material gathered independently of the model provider:\\n\'+evidence[:28000]+\'\\n\\nAnswer from this material. Cite direct source URLs actually present. Distinguish publication dates from page text when uncertain. Do not invent sources or current facts.\'\\n            msgs=[{\'role\':\'system\',\'content\':RESEARCH_SYSTEM},{\'role\':\'user\',\'content\':synth}]\\n            out=adaptive_chat(msgs,\'research\',4600,0.2)\\n            return save(out,state.get(\'last_adaptive_provider\'))\\n        if route==\'write\':\\n            msgs=[{\'role\':\'system\',\'content\':WRITE_SYSTEM}]+hist+[{\'role\':\'user\',\'content\':text[:16000]}]\\n            out=adaptive_chat(msgs,\'write\',5200,0.65)\\n            return save(out,state.get(\'last_adaptive_provider\'))\\n        if route==\'deep\':\\n            msgs=[{\'role\':\'system\',\'content\':DEEP_SYSTEM}]+hist+[{\'role\':\'user\',\'content\':text[:14000]}]\\n            out=adaptive_chat(msgs,\'deep\',5000,0.3)\\n            return save(out,state.get(\'last_adaptive_provider\'))\\n        msgs=[{\'role\':\'system\',\'content\':BASE_SYSTEM}]+hist+[{\'role\':\'user\',\'content\':text[:10000]}]\\n        out=adaptive_chat(msgs,\'fast\',2800,0.35)\\n        return save(out,state.get(\'last_adaptive_provider\'))\\n    except Exception as e:\\n        print(\'PRIMARY_ROUTE_ERROR\',cleanerr(e),flush=True);state[\'last_error\']=cleanerr(e)\\n        if route==\'research\':\\n            return save(\'Не удалось получить независимые веб-источники для этого запроса. Актуальные факты не буду подменять памятью модели.\',\'research-error-no-fabrication\')\\n        fallback=[{\'role\':\'system\',\'content\':BASE_SYSTEM}]+hist+[{\'role\':\'user\',\'content\':text[:10000]}]\\n        try:\\n            out=adaptive_chat(fallback,\'fallback\',3200,0.35)\\n            return save(out,state.get(\'last_adaptive_provider\'))\\n        except Exception as final_e:\\n            state[\'last_error\']=cleanerr(final_e)\\n            print(\'ALL_AI_ROUTES_UNAVAILABLE\',cleanerr(final_e),flush=True)\\n            degraded=(\'Сейчас все доступные ИИ-маршруты временно недоступны или исчерпали лимиты. \'\\n                      \'Контекст последних сообщений сохраняется в VK. Следующий запрос автоматически \'\\n                      \'снова проверит доступные маршруты.\')\\n            return save(degraded,\'degraded-no-provider\')\\n"\nsrc=_pre+_adaptive_code+_new_rr+_rr_end+_post\n\n_groq_gate="                if not GROQ_API_KEY:send(peer,\'AI-контур временно недоступен: GROQ_API_KEY не настроен.\');return\\n"\n_adaptive_gate="                if not _any_adaptive_provider():send(peer,\'AI-контур временно недоступен: ни один провайдер не настроен.\');return\\n"\nif _groq_gate not in src:\n    raise RuntimeError(\'V18 Groq hard-gate marker missing\')\nsrc=src.replace(_groq_gate,_adaptive_gate,1)\n\n_thread_marker="threading.Thread(target=startup,daemon=True).start()\\n"\nif _thread_marker not in src:\n    raise RuntimeError(\'V18 startup thread marker missing\')\nsrc=src.replace(_thread_marker,"threading.Thread(target=adaptive_startup_probe,daemon=True).start()\\n"+_thread_marker,1)\n\nsrc=src.replace(\'ND_VK_GATEWAY_V15B_FATHER_MIN_PROFILE_START\',\'ND_VK_GATEWAY_V18_ADAPTIVE_ROUTER_START\',1)\n'
inject="v18_patch_code="+repr(v18_patch_code)+"\nv17_patch_code += '\\n'+v18_patch_code\n"
outer=outer.replace(marker,inject+marker,1)

print('ND_V18_ADAPTIVE_ROUTER_WRAPPER_READY',flush=True)
exec(compile(outer,'nd_vk_gateway_v18_adaptive_router.py','exec'))
